import json,pathlib
chapters=[]
def A(key,group,title,images,voice,steps,check,tip='',audience='همه',short=None):
 chapters.append(dict(id=key,group=group,title=title,images=images.split(','),voice=voice,steps=steps.split('|'),check=check,tip=tip,audience=audience,short=short))
A('welcome','شروع','معرفی NiK Smart Count','dashboard','سلام! در این آموزش، کار با نیک اسمارت کانت ساختمانی را از اولین ورود تا ثبت بل، پرداخت، معاش، راپور و مدیریت کارمند یاد می‌گیریم. تمام عکس‌ها مربوط به یک شرکت ساختگی است. هر فصل یک کار مشخص دارد؛ همان کار را در حساب آزمایشی خودت انجام بده و بعد نتیجه را مقایسه کن.','اول مسیر «معرفی کوتاه» یا «آموزش کامل» را انتخاب کن.|روی عکس کلیک کن تا کلان شود؛ دکمه‌های داخل عکس، تصویر آموزشی‌اند.|برای ضبط، حالت ویدیو و تمام‌صفحه را روشن کن؛ با کلید فاصله به صحنهٔ بعد برو.','این رهنما بدون اینترنت باز می‌شود؛ خود برنامه برای ورود و ثبت در سرور به اینترنت نیاز دارد.','این فایل صدا یا ویدیوی آماده ندارد؛ متن گفتار را بخوان و صدای خودت را ضبط کن.',short='با نیک اسمارت کانت، مصرف، پرداخت، باقی‌داری و راپور پروژه‌های ساختمانی را از یک جا پیگیری می‌کنیم.')
A('account','شروع','حساب را چه کسی می‌سازد؟','office7-users,office7-permissions','اول باید برای شرکت حساب مالک ساخته شود. این کار را مدیر سامانه در دفتر هفت انجام می‌دهد. برای مالک، ایمیل واقعی، نقش مناسب، مدت پکیج و ظرفیت کارمند تعیین می‌شود. مالک بعداً حساب کارمندهای شرکت خود را می‌سازد. دفتر هفت مخصوص مدیر سامانه است؛ داشتن حساب مالک به معنی دسترسی به دفتر هفت نیست.','مدیر سامانه: Office Seven → Users → ساخت حساب.|نام، نام کاربری یکتا و ایمیل واقعی مالک را درج کن.|نقش مالک، مدت پکیج، خدمات مجاز و ظرفیت کارمند را تعیین کن.|اطلاعات ورود را خصوصی تحویل بده؛ در ویدیو رمز واقعی را نشان نده.','مالک به شرکت خودش وارد می‌شود؛ کارمند به همان شرکت و در حد صلاحیتش دسترسی دارد.','حساب کاربری با پروژه و کارمند معاش‌بگیر فرق دارد.',audience='مدیر سامانه')
A('login','شروع','اولین ورود به حساب','login','سایت را با آدرس درست و HTTPS باز می‌کنیم. مالک و کارمند از صفحهٔ ورود عادی استفاده می‌کنند. نام کاربری و رمز را وارد و Sign in را انتخاب می‌کنیم. رمز را در ویدیو و اسکرین‌شوت نشان ندهید. اگر نام یا رمز اشتباه باشد، دوباره بررسی می‌کنیم؛ حساب جدید یا نصب دوباره لازم نیست.','مالک و کارمند: /login.php.|مدیر سامانه: /office7-login.php.|نام کاربری و رمز حساب خودت را وارد کن.|Sign in را بزن؛ مرحلهٔ کُد ایمیل را تکمیل کن.','ورود موفق، فضای کار همان شرکت را باز می‌کند.','رمز یا کُد ایمیل را برای پشتیبانی و داخل گروه‌ها نفرست.',short='هر شخص با حساب خودش وارد می‌شود؛ برای مالک و کارمند، صلاحیت جدا تعیین می‌کنیم.')
A('verification','شروع','کُد ایمیل و اعتماد به دستگاه','verification','بعد از نام و رمز صحیح، کُد شش‌رقمی به ایمیل همان حساب می‌رود. کُد را وارد می‌کنیم. اگر دستگاه شخصی خودت است، Trust this device را انتخاب کن. این اعتماد تا سی روز است؛ با تغییر IP یا مشخصات مرورگر، یا تغییر رمز و باطل‌شدن نشست، تأیید تازه لازم می‌شود. در دستگاه مشترک این گزینه را انتخاب نکن.','ایمیل و پوشهٔ Spam را ببین.|کُد شش‌رقمی را پیش از پایان پنج دقیقه درج کن.|فقط در دستگاه شخصی Trust this device را تیک کن.|Verify and sign in را بزن.','بدون تأیید لازم، اطلاعات شرکت باز نمی‌شود.','تغییر وای‌فای، سیم‌کارت یا VPN می‌تواند باعث درخواست دوبارهٔ کُد شود؛ شمارش پنج ورود حذف شده است.')
A('blocked','شروع','ختم پکیج، قفل حساب و نشست تمام‌شده','account-status','اگر پکیج تمام شده یا مدیریت حساب را بسته باشد، پس از تأیید نام و رمز، دلیل مشخص نشان داده می‌شود. این حالت با اشتباه‌بودن رمز فرق دارد. از دکمه‌های تماس، واتس‌اپ یا ایمیل برای پیگیری استفاده می‌کنیم. اگر فقط نشست قبلی تمام شده باشد، دوباره وارد حساب می‌شویم؛ برای حل آن معلومات ثبت‌نشدهٔ مرورگر را پاک نمی‌کنیم.','پیام صفحه را بخوان؛ ختم پکیج، قفل یا غیرفعال‌شدن را تشخیص بده.|برای تمدید یا بررسی، از راه‌های پشتیبانی استفاده کن.|پس از فعال‌شدن، از صفحهٔ ورود دوباره وارد شو.|اگر ثبت تأییدنشده داری، نسخهٔ محفوظ را دانلود کن.','بستن دسترسی، اسناد مالی را خودکار حذف نمی‌کند.','این صفحه راه دورزدن قفل حساب نیست.')
A('header','آشنایی','هدر، پروژهٔ فعال و منوها','header','قبل از هر ثبت، پروژهٔ فعال را می‌بینیم. این مهم‌ترین عادت کاری است تا مصرف یک تعمیر در تعمیر دیگر ثبت نشود. عملیات سریع برای ثبت‌های پرتکرار است. زبان، روشن یا تاریک‌بودن صفحه و منوی حساب از هدر در دسترس‌اند. در موبایل، منوی سه‌خط فهرست بخش‌ها را باز می‌کند.','نام پروژهٔ فعال را بررسی کن.|از انتخاب پروژه، تعمیر درست را باز کن.|از عملیات سریع برای کارهای پرتکرار استفاده کن.|زبان و اندازهٔ مناسب را انتخاب کن؛ گزینه‌های پنهان را با مالک بررسی کن.','فهرست و فورم‌ها باید مربوط به همان پروژه باشند.','ندیدن یک گزینه ممکن است نتیجهٔ صلاحیت حساب باشد، نه خرابی برنامه.')
A('dashboard','آشنایی','داشبورد: مصرف، پرداخت و قرض','dashboard','در داشبورد سه عدد را با هم می‌خوانیم: مجموع مصارف، پول پرداخت‌شده و باقی‌داری. مصرف یعنی بل یا هزینهٔ ثبت‌شده؛ پرداخت یعنی پولی که واقعاً داده‌ایم. در مثال ما دو بل به ارزش صدوسی‌وهفت دالر و پنجاه سنت داریم. صدودوازده دالر و پنجاه سنت پرداخت شده و بیست‌وپنج دالر باقی است. روی جزئیات هر عدد می‌توانیم تراکنش‌های مربوط را ببینیم.','Total Expenses را با بل‌ها مقایسه کن.|Total Paid Out را با رسیدهای واقعی مقایسه کن.|Remaining Liabilities را با قرض‌های باز مقایسه کن.|نمودار و جزئیات را برای فهم منبع عدد باز کن.','در مثال: ۱۳۷٫۵۰ = ۱۱۲٫۵۰ + ۲۵٫۰۰ دالر.','شاخص جریان نقدی فروش و پرداخت را معادل موجودی واقعی بانک یا تمام سرمایهٔ شرکت حساب نکن؛ دفتر حسابداری را هم ببین.',short='مصرف با پرداخت فرق دارد. این‌جا می‌بینیم چقدر هزینه ثبت شده، چقدر پرداخت شده و چقدر قرض باقی مانده است.')
A('projects','پروژه و سرمایه','ساخت پروژه، قدم‌به‌قدم','projects,projects-form,project-budget,project-initial-expenses','از Projects یک پروژهٔ تازه می‌سازیم. نام، کُد، شهر، آدرس، منزل‌ها و واحدها را مشخص می‌کنیم. اسعار پایه و نرخ تبدیل را با دقت انتخاب می‌کنیم. بودجه و مصارف اولیه اختیاری‌اند؛ اگر هنوز معلوم نیستند، خالی می‌مانند تا بعداً ثبت شوند. ثبت نهایی را یک بار می‌زنیم و بعد از تأیید، پروژه را در فهرست می‌بینیم.','New Building Project را بزن.|مثال: NiK Training Tower، کُد NIK-DEMO-001، شهر کابل.|اسعار USD و نرخ ۷۰ افغانی برای یک دالر را تعیین کن.|بودجه و مصارف اولیه را بررسی و ثبت نهایی کن.|پروژه را انتخاب و بعد از تازه‌کردن صفحه دوباره بررسی کن.','نام و مشخصات پروژه باقی می‌ماند؛ ردیف خالی مصرف نباید هزینهٔ اضافی بسازد.','Delete پروژه را برای اصلاح نام استفاده نکن؛ اول Edit را انتخاب کن. حذف پروژه می‌تواند اسناد آن را هم تحت تأثیر قرار بدهد.',short='اول پروژه را با نام، موقعیت، تعداد منزل، تعداد واحد و اسعار درست تعریف می‌کنیم.')
A('partners','پروژه و سرمایه','شرکا و سرمایه‌گذاری','partners','شرکا را از کارت همان پروژه باز می‌کنیم. سهم شریک با مبلغی که واقعاً سرمایه آورده یکسان نیست. اول هویت و سهم یا توافق را درج می‌کنیم؛ سپس هر سرمایه‌گذاری واقعی را با تاریخ، مبلغ، اسعار و سند خودش ثبت می‌کنیم. برای تصمیم‌گیری، مبلغ سرمایه را با دفتر حسابداری و اسناد تحویل پول مقایسه می‌کنیم.','Projects → کارت پروژه → Partners Investors.|نام شریک و سهم یا توافق را طبق سند ثبت کن.|هر ورود واقعی سرمایه را جدا و با تاریخ ثبت کن.|جمع سهم‌ها و سرمایه‌ها را با قرارداد و اسناد تطبیق کن.','ثبت نام شریک به‌تنهایی به معنی دریافت پول نیست.','پول شخصی، سرمایه، قرض و فروش را به جای یکدیگر ثبت نکن.')
A('budget','پروژه و سرمایه','بودجه و مقایسه با مصرف','budget,budget-form','بودجه پول پرداخت‌شده نیست؛ برنامهٔ هزینه‌کردن پروژه است. در Set Budget، برای حساب یا دستهٔ درست مبلغ تعیین می‌کنیم. بعد مصرف واقعی، پرداخت، باقی‌داری و بودجهٔ باقی‌مانده را کنار هم می‌خوانیم. اگر ردیفی بودجه ندارد، در فهرست مصارف بدون بودجه دیده می‌شود و باید بررسی شود.','Budget → Set Budget.|دسته یا حساب مصرف را درست انتخاب کن.|مثال: بودجهٔ مصالح ۱۰۰۰ دالر.|مصرف واقعی و Remaining Budget را با بودجه تطبیق کن.','در یک مثال مستقل، بودجهٔ ۱۰۰۰ و مصرف ۱۳۷٫۵۰، باقی‌ماندهٔ ۸۶۲٫۵۰ می‌دهد.','بودجه را فقط برای پنهان‌کردن اضافه‌مصرف زیاد نکن؛ تغییر باید دلیل و تأیید داشته باشد.')
A('suppliers','طرف‌های حساب','عرضه‌کننده و فروشنده','suppliers,suppliers-form','قبل از خرید قرضی، فروشنده را معرفی می‌کنیم تا باقی‌داری به شخص درست وصل شود. نام، جنس عرضه‌شده و شمارهٔ تماس را درج می‌کنیم. مبلغ خرید ابتدایی فقط وقتی درج می‌شود که واقعاً خرید یا سابقهٔ مشخصی داریم. برای هر خرید بعدی، بل را در بخش مربوط ثبت می‌کنیم؛ همان خرید را دوباره در چند بخش تکرار نمی‌کنیم.','Suppliers → Add Supplier.|مثال: NiK Training Supplier؛ مواد: Cement and transport.|تلفن و حساب بانکی یا صرافی را در صورت نیاز درج کن.|در بل خرید، همین فروشنده را انتخاب یا درج کن.','خرید، پرداخت و باقی‌داری فروشنده باید با اسنادش همخوان باشد.','اگر خرید قرضی است، طرف حساب را خالی نگذار؛ پیدا کردن و تسویهٔ قرض بعداً دشوار می‌شود.')
A('contractors','طرف‌های حساب','قراردادی و قرارداد نرخ فی واحد','contractors,contractors-form','برای قراردادی، نوع کار و واحد اندازه‌گیری را مشخص می‌کنیم. نرخ فی واحد ضرب در مقدار کار، مبلغ قرارداد را می‌سازد. اگر قرارداد یک مبلغ ثابت دارد، همان گزینهٔ مربوط را طبق توافق استفاده می‌کنیم. مبلغ کل قرارداد، کار انجام‌شده و پول پرداخت‌شده را جدا می‌خوانیم؛ تمام ارزش قرارداد لزوماً امروز پرداختنی نیست.','Contractors → Add Contractor.|نام، نوع کار، تاریخ و واحد اندازه‌گیری را درج کن.|مثال: ۱۰۰ متر مربع × ۲۰۰ افغانی = ۲۰۰۰۰ افغانی.|شرایط پرداخت و تضمین/Retention را طبق قرارداد درج کن.','نرخ، مقدار و مجموع قرارداد باید با سند توافق برابر باشد.','مبلغ قرارداد را با صورت‌وضعیت تأییدشده یا رسید پرداخت اشتباه نکن.')
A('expenses','ثبت روزانه','بل خرید و مصرف با مثال واقعی','expenses,expenses-form','برای ثبت مصرف، نام جنس، مقدار، واحد و نرخ را وارد می‌کنیم. در مثال اول سه خریطه سمنت با نرخ دوازده دالر و پنجاه سنت، سی‌وهفت دالر و پنجاه سنت می‌شود. فروشنده و دستهٔ مصرف را هم درست انتخاب می‌کنیم. دوازده دالر و پنجاه سنت پرداخت شده و بیست‌وپنج دالر قرض می‌ماند. عکس بل را ضمیمه و بعد ثبت را تأیید می‌کنیم.','Expenses → Add Expense.|جنس: Cement؛ مقدار ۳؛ واحد bag؛ فی واحد ۱۲٫۵۰ USD.|فروشنده و دستهٔ مصالح را مشخص کن.|Partial cash را انتخاب و پرداخت ۱۲٫۵۰ را درج کن.|ثبت کن و بعد از refresh، بل و باقی‌داری را دوباره ببین.','مجموع ۳۷٫۵۰؛ پرداخت ۱۲٫۵۰؛ باقی ۲۵٫۰۰؛ یک پرداخت مرتبط.','اگر کل بل را نقدی انتخاب کنی، همان مبلغ را دوباره از Payments پرداخت نکن.',short='در هر بل، مقدار، واحد، نرخ، فروشنده و وضعیت نقد یا قرض را مشخص می‌کنیم؛ عکس سند را هم می‌گذاریم.')
A('currency','ثبت روزانه','افغانی و دالر را درست ثبت کن','expenses-form,payments-form','اسعار همان پول واقعی معامله است. در مثال دوم، دو مرتبه ترانسپورت با نرخ سه‌هزاروپنجصد افغانی داریم؛ مجموع هفت‌هزار افغانی است. با نرخ هفتاد، معادل صد دالر می‌شود. مبلغ را به اسعار خودش درج می‌کنیم و نرخ را جدا می‌نویسیم. جمع افغانی و دالر بدون تبدیل درست، معنی حسابداری ندارد.','اسعار AFN را انتخاب کن.|مقدار ۲ و نرخ فی واحد ۳۵۰۰ را درج کن.|نرخ تبدیل را ۷۰ بگذار.|Fully cash را فقط وقتی انتخاب کن که تمام ۷۰۰۰ افغانی پرداخت شده باشد.','۷۰۰۰ ÷ ۷۰ = ۱۰۰ USD؛ باقی‌داری این بل نقدی صفر است.','نرخ ۷۰ فقط برای مثال آموزشی است؛ نرخ واقعی روز معامله را استفاده کن.')
A('documents-state','ثبت روزانه','تأیید، رد، قفل و برگشت سند','expenses','پس از ثبت، سند را با اصل بل بررسی می‌کنیم. Approve برای تأیید، Reject برای رد و خارج‌کردن از حساب، و Post برای قفل‌کردن سند نهایی است. Reverse برای اصلاح حسابداری با نگه‌داشتن سابقهٔ اصل سند استفاده می‌شود. بعد از هر عمل، اثر آن را در راپور می‌بینیم؛ حذف عجولانه جای اصلاح حسابداری را نمی‌گیرد.','بل، مبلغ، تاریخ، فروشنده و ضمیمه را بررسی کن.|با صلاحیت مناسب Approve یا Reject را انتخاب کن.|برای نهایی‌کردن سند درست، Post (lock) را بزن.|برای اشتباه سند نهایی، مسیر Reverse و سند اصلاحی را بررسی کن.','وضعیت سند و اثر آن در راپور باید با تصمیم تأییدکننده یکسان باشد.','چرخهٔ کامل تمام انواع برگشت و اسناد پیچیده هنوز جداگانه نیاز به تطبیق حسابداری دارد؛ اول با سند ساختگی تمرین کن.')
A('payments','ثبت روزانه','پرداخت و رسید؛ از قرض کم کن','payments,payments-form','Payments جای ثبت پولی است که واقعاً پرداخت شده است. اگر قرض قبلاً ثبت شده، طرف حساب و تعهد مرتبط را انتخاب می‌کنیم تا همان قرض کم شود. پرداخت سفارشی بدون ارتباط ممکن است فقط خروج پول ثبت کند؛ بنابراین پس از ثبت، باقی‌داری همان بل را هم کنترل می‌کنیم. شمارهٔ رسید و نام بانک یا صرافی را برای پیدا کردن سند نگه می‌داریم.','Payments → Add Payment.|طرف حساب دارای قرض و تعهد درست را انتخاب کن.|مبلغ، تاریخ، روش پرداخت و شمارهٔ رسید را درج کن.|رسید پرداخت را ضمیمه کن.|بعد از ثبت، هم فهرست پرداخت و هم باقی‌داری فروشنده/بل را ببین.','برای قرض ۲۵ دالری، پرداخت مرتبط ۲۵ باید همان قرض را صفر کند.','پرداختی که هنگام ثبت بل خودکار ساخته شده را دوباره ثبت نکن.',short='پرداخت را به قرض و طرف حساب درست وصل می‌کنیم تا پول پرداخت‌شده و باقی‌داری دوباره‌شماری نشود.')
A('steel','مصالح و کارگاه','خرید سیخ‌گول، وزن و موجودی','steel,steel-form','در خرید سیخ، واحد و مشخصات فنی بسیار مهم‌اند. قطر، طول، تعداد یا وزن واقعی و نوع سیخ را طبق بل وارد می‌کنیم. تن با کیلوگرام فرق دارد؛ یک تن هزار کیلوگرام است. وزن تخمینی جدول یا حافظهٔ وزن را با باسکول و سند واقعی مقایسه می‌کنیم. سپس مبلغ، اسعار و وضعیت پرداخت را ثبت می‌کنیم.','Steel → Record Steel Purchase.|فروشنده، مشخصات سیخ و واحد اندازه‌گیری را انتخاب کن.|وزن یا تعداد واقعی، نرخ و ضمیمهٔ بل را درج کن.|نقد، قرض یا پرداخت قسمی را درست تعیین کن.|Stock & Kardex و Rebar Weight Memory را برای پیگیری ببین.','مقدار، واحد، مجموع قیمت و باقی‌داری باید با بل و رسید وزن برابر باشد.','ثبت در Steel و دوباره همان بل در Expenses می‌تواند هزینه را تکرار کند؛ یک سند را در مسیر اصلی خودش ثبت کن.')
A('concrete','مصالح و کارگاه','کانکریت و پمپ','concrete,concrete-form','در کانکریت، حجم متر مکعب، نرخ و محل مصرف را از بل می‌گیریم. هزینهٔ پمپ یا هزینهٔ اضافی را در فیلد مربوط جدا می‌نویسیم؛ آن را دو بار به مجموع اضافه نمی‌کنیم. اگر پرداخت قسمی است، مبلغ واقعی پرداخت را درج می‌کنیم. گزارش حجم و قیمت را با سند تحویل کانکریت تطبیق می‌کنیم.','Concrete → Record Concrete Pour.|تاریخ، فروشنده، محل و حجم m³ را درج کن.|نرخ فی متر مکعب و هزینهٔ پمپ را طبق بل تعیین کن.|وضعیت پرداخت و ضمیمهٔ سند را ثبت کن.|حجم و مجموع هزینه را در گزارش پروژه کنترل کن.','مثال مستقل: ۱۰ m³ × ۵۰ USD = ۵۰۰ USD، پیش از هزینه‌های اضافی ثبت‌شده.','حجم کانکریت را با مساحت متر مربع یا وزن اشتباه نکن.')
A('labor','معاشات','کارمند معاش‌بگیر با یوزر ورود فرق دارد','labor-form,labor-profile','در Labor & Payroll مشخصات کارمند یا کارگر و شرایط معاش را تعریف می‌کنیم. این پروفایل، خودکار حساب ورود به سایت نمی‌سازد. نوع معاش می‌تواند روزانه، هفتگی، ماهانه، ساعتی یا دورهٔ دلخواه باشد. تاریخ شروع، پروژه‌های مربوط و نرخ توافق‌شده را طبق قرارداد کار مشخص می‌کنیم.','Add Employee Profile را انتخاب کن.|نام، وظیفه و پروژه یا پروژه‌های مربوط را درج کن.|نوع معاش، نرخ، اسعار و تاریخ شروع را مشخص کن.|ساعات، اضافه‌کاری و کسر را فقط در صورت داشتن قاعدهٔ مشخص فعال کن.','پروفایل در فهرست کارمندان پروژه دیده می‌شود؛ هنوز پرداخت نقدی انجام نشده است.','برای ساخت یوزر ورود، به Staff Management برو؛ این دو بخش کار جدا دارند.')
A('earned','معاشات','اول استحقاق؛ بعد پرداخت معاش','labor-earned,labor-cash,labor','پس از تعریف کارمند، کار یا دورهٔ انجام‌شده را ثبت می‌کنیم. استحقاق یعنی شرکت برای کار انجام‌شده بدهکار شده؛ به معنی پرداخت پول نیست. بعد در Pay Cash Wage، پول واقعی داده‌شده را ثبت می‌کنیم. در یک مثال مستقل، دو روز کار با نرخ هزار افغانی، دوهزار افغانی استحقاق می‌دهد؛ با پرداخت هزاروپانصد، پانصد افغانی باقی می‌ماند.','Record Earned Wages را برای کار انجام‌شده باز کن.|کارمند، پروژه، دوره و مقدار کار را طبق حاضری درج کن.|استحقاق را بررسی کن؛ پرداخت نقدی باید هنوز جدا باشد.|Pay Cash Wage را برای پول واقعی پرداخت‌شده استفاده کن.|معاش، پیش‌پرداخت، کسر و باقی را با اسناد تطبیق کن.','مثال: ۲۰۰۰ استحقاق − ۱۵۰۰ پرداخت = ۵۰۰ AFN باقی.','پیش‌پرداخت را هم‌زمان به عنوان مصرف نهایی و پرداخت دوباره ثبت نکن؛ دوره‌ها را هم‌پوشان نساز.')
A('assets','اموال و فروش','اموال، ماشین‌آلات و کارت دارایی','assets,assets-form','دارایی مثل میکسر یا ماشین‌آلات را از مصرف روزمره جدا معرفی می‌کنیم. مشخصات، تاریخ خرید، ارزش، موقعیت و مسئول نگهداری را درج می‌کنیم. اگر استهلاک یا وضعیت انتقال در فورم موجود است، مطابق روش حسابداری شرکت تنظیم می‌کنیم. کارت دارایی برای پیدا کردن و شمارش واقعی اموال استفاده می‌شود.','Assets → Register new asset / machinery.|نام، کُد یا نمبر سریال، تاریخ و قیمت خرید را درج کن.|پروژه، وضعیت و مسئول را مشخص کن.|کارت یا فهرست اموال را برای شمارش چاپ کن.','یک دارایی باید با خود وسیله، سند خرید و مسئول آن قابل تطبیق باشد.','خرید دارایی را خودسرانه در چند بخش دوباره مصرف حساب نکن؛ طبقه‌بندی و استهلاک را حسابدار تأیید کند.')
A('apartments','اموال و فروش','واحد، آپارتمان و فروش','apartments,apartments-form','اول مشخصات واقعی واحد را ثبت می‌کنیم: نمبر، منزل، مساحت، جهت و نوع. Available یعنی آمادهٔ فروش، Reserved یعنی رزرو و Sold یعنی فروخته‌شده. در فروش، قیمت کل قرارداد با پول دریافت‌شده فرق دارد. دریافت هر قسط باید سند خودش را داشته باشد؛ مبلغ کل قرارداد را دریافت نقدی حساب نمی‌کنیم.','Apartments & Sales → Add Unit / Apartment.|نمبر، منزل، مساحت و نوع واحد را درج کن.|وضعیت Available، Reserved یا Sold را مطابق واقعیت تعیین کن.|قیمت و مشخصات خریدار/قرارداد را تکمیل کن.|اقساط و باقی‌داری خریدار را با رسیدها تطبیق کن.','مثال مستقل: قیمت ۵۰۰۰۰ و دریافت ۲۰۰۰۰، طلب باقی ۳۰۰۰۰ USD است.','Reserved را بدون قرارداد و دریافت واقعی، فروش نقدی تکمیل‌شده حساب نکن.')
A('exchange','ثبت روزانه','حواله و صرافی؛ دستور با پرداخت فرق دارد','exchange,exchange-form','در صرافی ابتدا جهت پول را مشخص می‌کنیم: Money Out یا Money In. نام صراف، فرستنده، گیرنده، مبلغ، اسعار و شمارهٔ مرجع را ثبت می‌کنیم. Draft و Pending، پرداخت تکمیل‌شده نیستند. وقتی انتقال واقعاً تأیید و رسید دریافت شد، وضعیت درست را ثبت می‌کنیم. اگر مربوط به یک قرض است، تعهد مرتبط را انتخاب می‌کنیم.','Exchange → New Exchange Transaction.|جهت، پروژه، صراف، گیرنده و مرجع را تعیین کن.|مبلغ را با اسعار خودش وارد کن؛ نرخ تبدیل را در صورت نیاز ثبت کن.|Draft/Pending را تا تأیید واقعی، Paid/Received نساز.|رسید و ارتباط با قرض را بررسی کن.','افغانی و دالر در دو دفتر جدا دیده می‌شوند؛ صرف ساخت دستور نباید پرداخت واقعی بسازد.','دکمهٔ Example 50,000 AFN برای مثال است؛ در حساب واقعی با بی‌احتیاطی نزن.')
A('files','اسناد','فایل منیجر، بل و ضمیمه','documents,documents-form','در Files & Bills سندها را مربوط به پروژه و موضوع درست نگه می‌داریم. فولدر می‌سازیم، فایل واضح آپلود می‌کنیم و از بخش Bills اسناد مربوط را می‌بینیم. نام، تاریخ و ارتباط فایل با بل مهم است. آپلود عکس بل، خودش مبلغ مالی ثبت نمی‌کند؛ ثبت بل و ضمیمه دو کار مرتبط‌اند.','Files & Bills → New Folder یا Upload Files.|نام روشن بده؛ مثال: بل‌های سمنت، ماه عقرب.|فایل و پروژهٔ درست را انتخاب کن.|بعد از ثبت، بازشدن سند و ارتباطش با بل را بررسی کن.','سند باید قابل بازشدن و متعلق به همان پروژه و بل باشد.','حد حجم و نوع مجاز را از خود فورم ببین؛ عکس تار یا فایل ناشناس را استفاده نکن.')
A('trial','دفاتر و راپورها','تراز آزمایشی؛ مثال را جمع می‌کنیم','accounting','در Trial Balance جمع بدهکار و بستانکار را مقایسه می‌کنیم. برای دو خرید مثال، هزینهٔ در جریان ساخت صدوسی‌وهفت دالر و پنجاه سنت است؛ سهم صندوق صدودوازده دالر و پنجاه سنت و قرض فروشنده بیست‌وپنج دالر است. جمع دو طرف برابر می‌شود. برابر بودن تراز لازم است، اما به‌تنهایی ثابت نمی‌کند که دسته‌بندی، قیمت یا سند اصلی درست بوده است.','Accounting → Trial Balance.|جمع Debit و Credit را مقایسه کن.|در مثال: ۱۳۷٫۵۰ = ۱۱۲٫۵۰ + ۲۵٫۰۰.|روی سندها و دفتر روزنامه، منبع عدد را پیدا کن.|موجودی و سرمایهٔ ابتدای دوره را هم طبق سند ثبت و تطبیق کن.','جمع بدهکار و بستانکار برابر و با اسناد مثال قابل توضیح است.','تراز برابر می‌تواند هنوز شامل سند اشتباه یا دوباره باشد؛ فقط به علامت سبز اکتفا نکن.',short='راپور و دفتر حسابداری کمک می‌کند عددهای داشبورد را تا بل و رسید اصلی دنبال کنیم.')
A('statements','دفاتر و راپورها','سود و زیان، بیلانس و سود هر واحد','accounting-income,accounting-balance','هر راپور سؤال خودش را جواب می‌دهد. Income Statement نتیجهٔ درآمد و مصارف دوره را نشان می‌دهد. Balance Sheet دارایی، بدهی و سرمایه را مقایسه می‌کند. Per-Unit Profit برای بررسی نتیجهٔ واحدهاست. در پروژهٔ ساختمانی، جمع دریافت پول را به‌تنهایی سود حساب نمی‌کنیم؛ کار در جریان، قراردادها، هزینه‌ها و روش حسابداری هم مهم‌اند.','پروژه و دورهٔ درست را انتخاب کن.|Income Statement و Balance Sheet را جدا بخوان.|سرمایه و قرض را با درآمد اشتباه نکن.|نتیجه را قبل از تقسیم مفاد با حسابدار و اسناد تطبیق کن.','هر عدد باید تا سند و طبقه‌بندی حساب قابل توضیح باشد.','شناسایی درآمد فروش و هزینهٔ ساختمان باید مطابق روش حسابداری شرکت و قواعد محل بررسی شود.')
A('journal','دفاتر و راپورها','دفتر روزنامه و کُد حساب‌ها','accounting-journal,accounting-accounts','Journal Ledger مسیر ثبت‌های حسابداری است و Chart of Accounts فهرست حساب‌ها و کُدهای آن‌هاست. این بخش را برای پیدا کردن علت یک عدد استفاده می‌کنیم. اگر دستهٔ مصرف اشتباه باشد، اول سند و حساب مربوط را بررسی می‌کنیم. ساخت حساب یا تغییر طبقه‌بندی باید با مسئول حسابداری هماهنگ باشد.','Accounting → Journal Ledger.|تاریخ، مرجع، شرح و بدهکار/بستانکار را بررسی کن.|Chart of Accounts را برای معنی کُدها باز کن.|در اختلاف، به بل یا رسید مبنا برگرد.','عدد راپور با ثبت روزنامه و سند مبنا قابل پیگیری است.','برای برابر ساختن ظاهری تراز، سند بی‌دلیل نساز.')
A('reports','دفاتر و راپورها','راپور مدیریتی و خروجی','reports,report-materials,report-monthly','در Reports، راپور مالی، مصالح، قرض قراردادی‌ها، فروش و جریان نقدی ماهانه را جدا می‌بینیم. اول پروژه و تاریخ را درست انتخاب می‌کنیم. بعد مصارف و پرداخت را با دفاتر مقایسه می‌کنیم. Print برای چاپ و Export CSV برای بررسی در فایل جدولی است. فایل خروجی هم معلومات شرکت است و باید خصوصی نگه داشته شود.','Reports → نوع راپور را انتخاب کن.|پروژه، ماه و فیلترها را بررسی کن.|مصرف، پرداخت و باقی‌داری را با مثال و دفاتر تطبیق کن.|Print یا Export CSV را فقط در حد صلاحیت استفاده کن.','راپور مثال باید ۱۳۷٫۵۰ مصرف، ۱۱۲٫۵۰ پرداخت و ۲۵٫۰۰ قرض نشان بدهد.','یک راپور از دوره یا پروژهٔ دیگر را با عدد فعلی مقایسه نکن.')
A('staff','مدیریت دسترسی','مالک چگونه یوزر کارمند می‌سازد؟','team,team-form','مالک در Staff Management برای کارمند حساب ورود می‌سازد. ایمیل باید مال همان شخص و قابل دریافت باشد. نقش و دسترسی را مطابق وظیفه انتخاب می‌کنیم؛ حساب مشاهده‌گر برای دیدن است. کارمند بیشتر از سقف صلاحیت مالک دسترسی نمی‌گیرد. بعد از ساخت، با همان حساب آزمایشی وارد می‌شویم و گزینه‌های مجاز و پنهان را بررسی می‌کنیم.','Staff Management → Create account.|نام، نام کاربری، ایمیل واقعی و رمز قوی تعیین کن.|مشاهده، ثبت، ویرایش، حذف، تأیید، چاپ و خروجی را جدا تنظیم کن.|در صورت نیاز پروژه‌های مجاز را محدود کن.|با حساب کارمند، یک ثبت مجاز و یک عمل ممنوع را آزمایش کن.','کارمند فقط شرکت، پروژه‌ها و عملیات مجاز خودش را می‌بیند.','ظرفیت ساخت کارمند را دفتر هفت تعیین می‌کند؛ ساخت پروفایل معاش جای این حساب را نمی‌گیرد.',audience='مالک',short='مالک می‌تواند دسترسی هر کارمند را محدود کند؛ گزینه‌ای که اجازه ندارد از محیط کارش پنهان می‌شود.')
A('office','مدیریت دسترسی','دفتر هفت: پکیج و صلاحیت تمام بخش‌ها','office7-users,office7-permissions,office7-restrictions','این بخش مخصوص مدیر سامانه است. برای مالک و کارمند می‌توان خدمات، مشاهده و عملیات را جدا کنترل کرد. برای جلوگیری از کار، فقط رمز را تغییر نمی‌دهیم؛ وضعیت قفل، فعال‌بودن یا پکیج را درست تنظیم می‌کنیم. پیام روشن برای کاربر می‌نویسیم تا بداند چرا دسترسی بسته شده و چگونه پیگیری کند.','Office Seven → Users → Edit & permissions.|پکیج، تاریخ اعتبار، ظرفیت و وضعیت حساب را تعیین کن.|برای هر خدمت، مشاهده و عملیات مجاز را انتخاب کن.|در پیام حساب، دلیل قابل فهم بنویس.|از حساب آزمایشی، نتیجهٔ پنهان‌شدن یا قفل را بررسی کن.','محدودیت باید هم در نمایش و هم در عملیات سرور اجرا شود.','خاموش‌کردن مشاهده، آن بخش را پنهان می‌کند؛ دسترسی یک عمل با دسترسی دیدن فرق دارد.',audience='مدیر سامانه')
A('delete','مدیریت دسترسی','حذف دسترسی کارمند','delete-user','وقتی شخص دیگر نباید وارد شود، حساب درست را پیدا می‌کنیم. حذف دسترسی با حذف اسناد مالی فرق دارد. نام کاربری را برای تأیید دقیق می‌نویسیم. حساب از فهرست عادی خارج و ورودش بسته می‌شود؛ سابقهٔ مالی باید بماند. مالک دارای کارمند را بدون رسیدگی به کارمندان زیرمجموعه حذف نمی‌کنیم.','در فهرست یوزرها، شخص درست را انتخاب کن.|پیش از تأیید، شرکت و نام کاربری را بررسی کن.|نام کاربری خواسته‌شده را دقیق بنویس.|بعد از حذف، فهرست و بسته‌شدن ورود را کنترل کن.','دسترسی شخص بسته می‌شود؛ اسناد مالی به خاطر حذف یوزر پاک نمی‌شود.','نام کاربری یا ایمیل حذف‌شده ممکن است برای حفظ سابقه دوباره قابل استفاده نباشد.',audience='مالک / مدیر سامانه')
A('settings','تنظیمات و نگهداری','زبان، اندازه و ظاهر برنامه','settings','در Settings می‌توان زبان، اندازهٔ نوشته‌ها و ظاهر را برای استفادهٔ راحت‌تر تنظیم کرد. پیش‌فرض تازه انگلیسی است؛ انتخاب دستی قبلی حفظ می‌شود. نرخ پیش‌فرض شرکت را با نرخ هر معامله اشتباه نمی‌گیریم. تغییر ظاهر نیاز به تغییر حساب‌ها ندارد. پس از Save Settings، صفحه را تازه می‌کنیم تا مطمئن شویم تنظیم مانده است.','Settings → Language یا Interface size.|زبان انگلیسی، دری یا پشتو و اندازهٔ مناسب را انتخاب کن.|حالت روشن، تاریک یا خودکار را تعیین کن.|Save Settings را بزن و پس از refresh بررسی کن.','زبان انتخاب‌شده و تنظیم ذخیره‌شده باقی می‌ماند.','تم و رنگ، صحت محاسبات را تضمین نمی‌کند؛ اول خوانایی و استفادهٔ آسان را انتخاب کن.')
A('print','تنظیمات و نگهداری','لوگو و شکل بل، رسید و قرارداد','print-design','در Documents & print design، لوگو و معلوماتی را تنظیم می‌کنیم که روی سند چاپ می‌شود. نام، تماس، آدرس و معلومات بانکی را با دقت درج می‌کنیم. اندازهٔ کاغذ، فونت و حاشیه را انتخاب و یک سند آزمایشی چاپ می‌کنیم. نتیجه را روی خود کاغذ یا PDF هم می‌بینیم؛ فقط نمایش فورم کافی نیست.','لوگو و معلومات رسمی شرکت را درج کن.|A4، A5 یا حرارتی را مطابق چاپگر انتخاب کن.|فونت، حاشیه و بخش‌های سند را تنظیم کن.|Save design و سپس یک چاپ آزمایشی بگیر.','لوگو، تماس، مبلغ، تاریخ و امضاها باید واضح و در کاغذ جا شوند.','قالب JSON را بدون شناخت تغییر نده؛ از قالب پیش‌فرض و پشتیبان تنظیم استفاده کن.')
A('backup','تنظیمات و نگهداری','پشتیبان‌گیری و بازیابی','backup','آخر روز، نسخهٔ پشتیبان می‌گیریم و بیرون از دستگاه نگه می‌داریم. Export Local JSON یک فایل داده می‌دهد؛ این را به‌تنهایی جای بکاپ دیتابیس و آپلودهای هاست حساب نمی‌کنیم. Restore را اول در محیط آزمایشی امتحان می‌کنیم. نوشتهٔ Connected یا نصب افزونهٔ گوگل در چت، به‌تنهایی اثبات ارسال بکاپ از داخل برنامه به Drive نیست.','Export Local JSON را دانلود و با تاریخ نام‌گذاری کن.|بکاپ فایل‌ها و دیتابیس هاست را هم جدا نگه دار.|قبل از Restore، از وضعیت فعلی یک نسخهٔ تازه بگیر.|بازیابی را ابتدا روی نسخهٔ آزمایشی تمرین و نتیجه را تطبیق کن.','بکاپ خوب باید قابل بازیابی باشد، نه فقط قابل دانلود.','همگام‌سازی واقعی Google Drive و بازیابی تمام حالت‌ها هنوز به آزمون مستقل خدمات واقعی نیاز دارد.')
A('audit','تنظیمات و نگهداری','ثبت رویدادها و پیگیری تغییر','audit_logs','Audit Logs برای پیگیری این است که چه کسی چه کاری کرده است. در اختلاف، تاریخ، شخص، نوع عمل و سند مربوط را بررسی می‌کنیم. این تاریخچه را برای راحت‌ترشدن فهرست پاک نمی‌کنیم؛ ممکن است برای رسیدگی لازم باشد. دسترسی دیدن یا پاک‌کردن آن باید محدود باشد.','Audit Logs را باز کن.|با تاریخ و کاربر، رویداد مربوط را پیدا کن.|جزئیات را با بل و راپور تطبیق کن.|چاپ یا پاک‌کردن فقط با صلاحیت و ضرورت مشخص انجام شود.','اثر تغییر باید قابل پیگیری باشد.','پاک‌کردن تاریخچه، روش اصلاح اشتباه مالی نیست.')
A('support','تنظیمات و نگهداری','ایمیل امنیتی و تماس پشتیبانی','office7-system,security-email,support','مدیر سامانه از System می‌تواند فرستندهٔ کُد ایمیل و راه‌های تماس پشتیبانی را تنظیم کند. برای تغییر فرستنده، اول دریافت کُد آزمایشی را تأیید می‌کنیم و بعد ذخیره می‌زنیم. ایمیل امنیتی فرستنده با ایمیل پشتیبانی فرق دارد. شماره‌ها و آدرس را دقیق بررسی می‌کنیم تا کاربر قفل‌شده به جای درست تماس بگیرد.','Office Seven → System.|Security email settings: ارسال کُد آزمایشی، تأیید و ذخیره.|Support contact settings: تماس، واتس‌اپ و ایمیل را تعیین کن.|یک صفحهٔ وضعیت حساب آزمایشی را باز و لینک‌ها را بررسی کن.','کُد ورود از security@nik-smartcount.com؛ پشتیبانی info@niksmartcount.com؛ تماس +93783788278.','رمز ایمیل یا هاست را در رهنما و ریپو ننویس.',audience='مدیر سامانه')
A('mobile','موبایل','استفاده و نصب در موبایل','install,header','برنامه را با مرورگر اصلی موبایل باز می‌کنیم. در اندروید از منوی Chrome، Install app یا Add to Home screen را انتخاب می‌کنیم. در آیفون از Safari، Share و بعد Add to Home Screen را می‌زنیم. نصب، برنامه را از آیکن موبایل باز می‌کند؛ در این نسخه برای ورود و ثبت در سرور هنوز اینترنت لازم است.','Android: Chrome → ⋮ → Install app / Add to Home screen.|iPhone: Safari → Share → Add to Home Screen → Add.|بعد از نصب، از آیکن صفحهٔ اصلی باز کن.|پس از ثبت، تأیید سرور و باقی‌ماندن معلومات پس از refresh را ببین.','آیکن برنامه باز می‌شود؛ نصب به معنی آماده‌بودن کار آفلاین کامل نیست.','شروع آفلاین کامل و سینک پس از آن هنوز پیاده و تأیید نشده است.',short='در موبایل هم می‌توان برنامه را نصب کرد. برای ورود و ثبت روی سرور، در این نسخه اینترنت لازم است.')
A('routine','تمرین و پایان','برنامهٔ سادهٔ کار روزانه','dashboard,reports','اول روز پروژه، تاریخ و صلاحیت حساب را بررسی می‌کنیم. هر بل را یک بار و با سند واضح درج می‌کنیم. پرداخت واقعی را به تعهد درست وصل می‌کنیم. آخر روز، جمع مصارف، پرداخت، باقی‌داری و صندوق یا بانک را با اسناد تطبیق می‌کنیم. بعد نسخهٔ پشتیبان می‌گیریم و از دستگاه مشترک خارج می‌شویم.','اول روز: پروژه و تاریخ درست.|در جریان روز: ثبت یک‌بارهٔ بل و ضمیمهٔ سند.|هنگام پرداخت: رسید واقعی و ارتباط با قرض.|آخر روز: تطبیق راپور و دفتر با صندوق، بانک و اسناد.|پشتیبان‌گیری و خروج از دستگاه مشترک.','همکار دیگر هم باید بتواند با همان اسناد، عدد راپور را توضیح بدهد.','برای شروع واقعی، یک پروژهٔ ساختگی را از اول تا آخر با حسابدار تمرین کن.')
A('troubleshoot','تمرین و پایان','اگر ثبت نشد یا عدد فرق داشت','expenses,account-status','اگر پیام ثبت تأیید نشد آمد، دوباره‌سازی عجولانهٔ همان بل ممکن است سند تکراری بسازد. اول نسخهٔ محفوظ را می‌گیریم، اتصال و حساب را بررسی و از تلاش دوباره استفاده می‌کنیم. اگر عدد فرق داشت، پروژه، تاریخ، اسعار، نرخ، وضعیت سند، تکرار بل و ارتباط پرداخت را یکی‌یکی می‌بینیم.','ثبت تأیید نشد: نسخهٔ محفوظ را دانلود و پیام را نگه دار.|صفحه و حافظهٔ مرورگر را یک‌جا پاک نکن.|اختلاف عدد: پروژه، دوره، نرخ، وضعیت سند و تکرار را بررسی کن.|برای پشتیبانی عکس پیام بفرست؛ رمز و کُد را پنهان کن.','پیش از ثبت دوباره، معلوم شود سند قبلی روی سرور ثبت شده یا خیر.','مرورگر، خاموشی یا قطع اینترنت را معادل بکاپ حساب نکن.')
A('outro','تمرین و پایان','جمع‌بندی معرفی و راه تماس','dashboard','در این معرفی دیدیم که کار مرتب از پروژهٔ درست، سند واضح، نرخ صحیح، پرداخت مرتبط و راپور قابل تطبیق شروع می‌شود. برای آموزش کامل، فصل‌های مربوط به وظیفهٔ خودتان را تمرین کنید. برای پشتیبانی با شمارهٔ درج‌شده یا ایمیل تماس بگیرید. این نمونه‌ها آموزشی‌اند؛ پیش از حساب‌های واقعی، مراحل و جمع‌ها را با مسئول حسابداری تأیید کنید.','معرفی کوتاه را برای ویدیوی اول انتخاب کن.|آموزش کامل را فصل‌به‌فصل ضبط کن.|تمرین‌ها را با معلومات ساختگی انجام بده.|پشتیبانی: +93783788278 — info@niksmartcount.com.','یک کاربر تازه باید بتواند یک بل آزمایشی ثبت و نتیجهٔ آن را در راپور پیدا کند.','این رهنما تأییدیهٔ رسمی حسابرسی یا تضمین نبودِ هرگونه خطا نیست.',short='برای آموزش و پشتیبانی، با نیک اسمارت کانت در تماس شوید. تمرین را با پروژهٔ ساختگی شروع کنید و نتیجه را بررسی کنید.')
pathlib.Path(__file__).with_name('chapters.json').write_text(json.dumps(chapters,ensure_ascii=False,indent=2)+'\n')
print(len(chapters),'chapters prepared')
